import{_ as l,a0 as a,w as p,s as r,I as o,x as t,a1 as s,A as d,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Vim 入門：基礎 | LCTT x X-CMD","titleTemplate":false,"description":"Vim 入門：基礎 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim 入門：基礎 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim 入門：基礎 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190325 Getting started with Vim- The basics","title":"Vim 入門：基礎","tag":"201904","desc":""},"relativePath":"201904/20190325 Getting started with Vim- The basics.md","filePath":"[post].md"}'),m={name:"201904/20190325 Getting started with Vim- The basics.md"};function c(u,e,g,f,h,V){const i=a("Link");return p(),r("div",null,[e[30]||(e[30]=o("h1",{id:"vim-入門-基礎",tabindex:"-1"},[t("Vim 入門：基礎 "),o("a",{class:"header-anchor",href:"#vim-入門-基礎","aria-label":"Permalink to “Vim 入門：基礎”"},"​")],-1)),e[31]||(e[31]=o("blockquote",null,[o("p",null,"為工作或者新項目學習足夠的 Vim 知識。")],-1)),e[32]||(e[32]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/data_metrics_analytics_desktop_laptop.png?itok=9QXd7AUr",alt:"Person standing in front of a giant computer screen with numbers, data",title:"Person standing in front of a giant computer screen with numbers, data"})],-1)),e[33]||(e[33]=o("p",null,"我還清晰地記得我第一次接觸 Vim 的時候。那時我還是一名大學生，計算機學院的機房裏都裝着 Ubuntu 系統。儘管我在上大學前也曾接觸過不同的 Linux 發行版（比如 RHEL —— Red Hat 在百思買出售它的 CD），但這卻是我第一次要在日常中頻繁使用 Linux 系統，因為我的課程要求我這樣做。當我開始使用 Linux 時，正如我的前輩和將來的後繼者們一樣，我感覺自己像是一名“真正的程序員”了。",-1)),e[34]||(e[34]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/uploads/1_xkcdcartoon.jpg",alt:"Real Programmers comic",title:"Real Programmers comic"})],-1)),o("p",null,[o("em",null,[e[1]||(e[1]=t("真正的程序員，來自 ",-1)),s(i,{href:"https://xkcd.com/378/"},{default:d(()=>[...e[0]||(e[0]=[t("xkcd",-1)])]),_:1})])]),o("p",null,[e[4]||(e[4]=t("學生們可以使用像 ",-1)),s(i,{href:"https://kate-editor.org"},{default:d(()=>[...e[2]||(e[2]=[t("Kate",-1)])]),_:1}),e[5]||(e[5]=t(" 一樣的圖形文本編輯器，這也安裝在學校的電腦上了。對於那些可以使用 shell 但不習慣使用控制台編輯器的學生，最流行的選擇是 ",-1)),s(i,{href:"https://www.nano-editor.org"},{default:d(()=>[...e[3]||(e[3]=[t("Nano",-1)])]),_:1}),e[6]||(e[6]=t("，它提供了很好的交互式菜單和類似於 Windows 圖形文本編輯器的體驗。",-1))]),o("p",null,[e[9]||(e[9]=t("我有時會用 Nano，但當我聽説 ",-1)),s(i,{href:"https://www.vim.org"},{default:d(()=>[...e[7]||(e[7]=[t("Vi/Vim",-1)])]),_:1}),e[10]||(e[10]=t(" 和 ",-1)),s(i,{href:"https://www.gnu.org/software/emacs"},{default:d(()=>[...e[8]||(e[8]=[t("Emacs",-1)])]),_:1}),e[11]||(e[11]=t(" 能做一些很棒的事情時我決定試一試它們（主要是因為它們看起來很酷，而且我也很好奇它們有什麼特別之處）。第一次使用 Vim 時嚇到我了 —— 我不想搞砸任何事情！但是，一旦我掌握了它的訣竅，事情就變得容易得多，我就可以欣賞這個編輯器的強大功能了。至於 Emacs，呃，我有點放棄了，但我很高興我堅持和 Vim 在一起。",-1))]),e[35]||(e[35]=n(`<p>在本文中，我將介紹一下 Vim（基於我的個人經驗），這樣你就可以在 Linux 系統上用它來作為編輯器使用了。這篇文章不會讓你變成 Vim 的專家，甚至不會觸及 Vim 許多強大功能的皮毛。但是起點總是很重要的，我想讓開始的經歷儘可能簡單，剩下的則由你自己去探索。</p><h3 id="第-0-步-打開一個控制台窗口" tabindex="-1">第 0 步：打開一個控制台窗口 <a class="header-anchor" href="#第-0-步-打開一個控制台窗口" aria-label="Permalink to “第 0 步：打開一個控制台窗口”">​</a></h3><p>在使用 Vim 前，你需要做一些準備工作。在 Linux 操作系統打開控制台終端。（因為 Vim 也可以在 MacOS 上使用，Mac 用户也可以使用這些説明）。</p><p>打開終端窗口後，輸入 <code>ls</code> 命令列出當前目錄下的內容。然後，輸入 <code>mkdir Tutorial</code> 命令創建一個名為 <code>Tutorial</code> 的新目錄。通過輸入 <code>cd Tutorial</code> 來進入該目錄。</p><p><img src="https://opensource.com/sites/default/files/uploads/2_createtestfolder.jpg" alt="Create a folder" title="Create a folder"></p><p>這就是全部的準備工作。現在是時候轉到有趣的部分了——開始使用 Vim。</p><h3 id="第-1-步-創建一個-vim-文件和不保存退出" tabindex="-1">第 1 步：創建一個 Vim 文件和不保存退出 <a class="header-anchor" href="#第-1-步-創建一個-vim-文件和不保存退出" aria-label="Permalink to “第 1 步：創建一個 Vim 文件和不保存退出”">​</a></h3><p>還記得我一開始説過我不敢使用 Vim 嗎？我當時在害怕“如果我改變了一個現有的文件，把事情搞砸了怎麼辦？”畢竟，一些計算機科學作業要求我修改現有的文件。我想知道：<em>如何在不保存更改的情況下打開和關閉文件？</em></p><p>好消息是你可以使用相同的命令在 Vim 中創建或打開文件：<code>vim &lt;FILE_NAME&gt;</code>，其中 <code>&lt;FILE_NAME&gt;</code> 表示要創建或修改的目標文件名。讓我們通過輸入 <code>vim HelloWorld.java</code> 來創建一個名為 <code>HelloWorld.java</code> 的文件。</p><p>你好，Vim！現在，講一下 Vim 中一個非常重要的概念，可能也是最需要記住的：Vim 有多種模式，下面是 Vim 基礎中需要知道的的三種：</p><div class="table-wrap"><table><thead><tr><th>模式</th><th>描述</th></tr></thead><tbody><tr><td>正常模式</td><td>默認模式，用於導航和簡單編輯</td></tr><tr><td>插入模式</td><td>用於直接插入和修改文本</td></tr><tr><td>命令列模式</td><td>用於執行如保存，退出等命令</td></tr></tbody></table></div><p>Vim 也有其他模式，例如可視模式、選擇模式和命令模式。不過上面的三種模式對我們來説已經足夠用了。</p><p>你現在正處於正常模式，如果有文本，你可以用箭頭鍵移動或使用其他導航鍵（將在稍後看到）。要確定你正處於正常模式，只需按下 <code>esc</code> (Escape）鍵即可。</p><blockquote><p><strong>提示：</strong> <code>Esc</code> 切換到正常模式。即使你已經在正常模式下，點擊 <code>Esc</code> 只是為了練習。</p></blockquote><p>現在，有趣的事情發生了。輸入 <code>:</code> （冒號鍵）並接着 <code>q!</code> （完整命令：<code>:q!</code>）。你的屏幕將顯示如下：</p><p><img src="https://opensource.com/sites/default/files/uploads/4_existingvim.jpg" alt="Editing Vim" title="Editing Vim"></p><p>在正常模式下輸入冒號會將 Vim 切換到命令列模式，執行 <code>:q!</code> 命令將退出 Vim 編輯器而不進行保存。換句話説，你放棄了所有的更改。你也可以使用 <code>ZQ</code> 命令；選擇你認為更方便的選項。</p><p>一旦你按下 <code>Enter</code> （回車），你就不再在 Vim 中。重複練習幾次來掌握這條命令。熟悉了這部分內容之後，請轉到下一節，瞭解如何對文件進行更改。</p><h3 id="第-2-步-在-vim-中修改並保存" tabindex="-1">第 2 步：在 Vim 中修改並保存 <a class="header-anchor" href="#第-2-步-在-vim-中修改並保存" aria-label="Permalink to “第 2 步：在 Vim 中修改並保存”">​</a></h3><p>通過輸入 <code>vim HelloWorld.java</code> 和回車鍵來再次打開這個文件。你可以在插入模式中修改文件。首先，通過 <code>Esc</code> 鍵來確定你正處於正常模式。接着輸入 <code>i</code> 來進入插入模式（沒錯，就是字母 <strong>i</strong>）。</p><p>在左下角，你將看到 <code>-- INSERT --</code>，這標誌着你這處於插入模式。</p><p><img src="https://opensource.com/sites/default/files/uploads/6_insertionmode.jpg" alt="Vim insert mode" title="Vim insert mode"></p><p>寫一些 Java 代碼。你可以寫任何你想寫的，不過這也有一份你可以參照的例子。你的屏幕將顯示如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class HelloWorld {</span></span>
<span class="line"><span>  public static void main([String][11][] args) {</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>非常漂亮！注意文本是如何在 Java 語法中高亮顯示的。因為這是個 Java 文件，所以 Vim 將自動檢測語法並高亮顏色。</p><p>保存文件：按下 <code>Esc</code> 來退出插入模式並進入命令列模式。輸入 <code>:</code> 並接着 <code>x!</code> （完整命令：<code>:x!</code>），按回車鍵來保存文件。你也可以輸入 <code>wq</code> 來執行相同的操作。</p><p>現在，你知道了如何使用插入模式輸入文本並使用以下命令保存文件：<code>:x!</code> 或者 <code>:wq</code>。</p><h3 id="第-3-步-vim-中的基本導航" tabindex="-1">第 3 步：Vim 中的基本導航 <a class="header-anchor" href="#第-3-步-vim-中的基本導航" aria-label="Permalink to “第 3 步：Vim 中的基本導航”">​</a></h3><p>雖然你總是可以使用上箭頭、下箭頭、左箭頭和右箭頭在文件中移動，但在一個幾乎有數不清行數的大文件中，這將是非常困難的。能夠在一行中跳躍光標將會是很有用的。雖然 Vim 提供了不少很棒的導航功能，不過在一開始，我想向你展示如何在 Vim 中到達某一特定的行。</p><p>單擊 <code>Esc</code> 來確定你處於正常模式，接着輸入 <code>:set number</code> 並鍵入回車。</p><p>瞧！你現在可以在每一行的左側看到行號。</p><p><img src="https://opensource.com/sites/default/files/uploads/10_setnumberresult_0.jpg" alt="Showing Line Numbers" title="Showing Line Numbers"></p><p>好，你也許會説，“這確實很酷，不過我該怎麼跳到某一行呢？”再一次的，確認你正處於正常模式。接着輸入 <code>:&lt;LINE_NUMBER&gt;</code>，在這裏 <code>&lt;LINE_NUMBER&gt;</code> 是你想去的那一行的行數。按下回車鍵來試着移動到第二行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:2</span></span></code></pre></div><p>現在，跳到第三行。</p><p><img src="https://opensource.com/sites/default/files/uploads/12_jumpintoline3.jpg" alt="Jump to line 3" title="Jump to line 3"></p><p>但是，假如你正在處理一個一千多行的文件，而你正想到文件底部。這該怎麼辦呢？確認你正處於正常模式，接着輸入 <code>:$</code> 並按下回車。</p><p>你將來到最後一行！</p><p>現在，你知道如何在行間跳躍了，作為補充，我們來學一下如何移動到一行的行尾。確認你正處於有文本內容的一行，如第三行，接着輸入 <code>$</code>。</p><p><img src="https://opensource.com/sites/default/files/uploads/14_gotolastcharacter.jpg" alt="Go to the last character" title="Go to the last character"></p><p>你現在來到這行的最後一個字節了。在此示例中，高亮左大括號以顯示光標移動到的位置，右大括號被高亮是因為它是高亮的左大括號的匹配字符。</p><p>這就是 Vim 中的基本導航功能。等等，別急着退出文件。讓我們轉到 Vim 中的基本編輯。不過，你可以暫時順便喝杯咖啡或茶休息一下。</p><h3 id="第-4-步-vim-中的基本編輯" tabindex="-1">第 4 步：Vim 中的基本編輯 <a class="header-anchor" href="#第-4-步-vim-中的基本編輯" aria-label="Permalink to “第 4 步：Vim 中的基本編輯”">​</a></h3><p>現在，你已經知道如何通過跳到想要的一行來在文件中導航，你可以使用這個技能在 Vim 中進行一些基本編輯。切換到插入模式。（還記得怎麼做嗎？是不是輸入 <code>i</code> ？）當然，你可以使用鍵盤逐一刪除或插入字符來進行編輯，但是 Vim 提供了更快捷的方法來編輯文件。</p><p>來到第三行，這裏的代碼是 <code>public static void main(String[] args) {</code>。雙擊 <code>d</code> 鍵，沒錯，就是 <code>dd</code>。如果你成功做到了，你將會看到，第三行消失了，剩下的所有行都向上移動了一行。（例如，第四行變成了第三行）。</p><p><img src="https://opensource.com/sites/default/files/uploads/15_deletinglines.jpg" alt="Deleting A Line" title="Deleting A Line"></p><p>這就是<ruby>刪除<rt>delete</rt></ruby>命令。不要擔心，鍵入 <code>u</code>，你會發現這一行又回來了。喔，這就是<ruby>撤銷<rt>undo</rt></ruby>命令。</p><p><img src="https://opensource.com/sites/default/files/uploads/16_undoingtheline.jpg" alt="Undoing a change in Vim" title="Undoing a change in Vim"></p><p>下一課是學習如何複製和粘貼文本，但首先，你需要學習如何在 Vim 中突出顯示文本。按下 <code>v</code> 並向左右移動光標來選擇或反選文本。當你向其他人展示代碼並希望標識你想讓他們注意到的代碼時，這個功能也非常有用。</p><p><img src="https://opensource.com/sites/default/files/uploads/17_highlighting.jpg" alt="Highlighting text in Vim" title="Highlighting text in Vim"></p><p>來到第四行，這裏的代碼是 <code>System.out.println(&quot;Hello, Opensource&quot;);</code>。高亮這一行的所有內容。好了嗎？當第四行的內容處於高亮時，按下 <code>y</code>。這就叫做<ruby>複製<rt>yank</rt></ruby>模式，文本將會被複制到剪貼板上。接下來，輸入 <code>o</code> 來創建新的一行。注意，這將讓你進入插入模式。通過按 <code>Esc</code> 退出插入模式，然後按下 <code>p</code>，代表<ruby>粘貼<rt>paste</rt></ruby>。這將把複製的文本從第三行粘貼到第四行。</p><p><img src="https://opensource.com/sites/default/files/uploads/19_pasting.jpg" alt="Pasting in Vim" title="Pasting in Vim"></p><p>作為練習，請重複這些步驟，但也要修改新創建的行中的文字。此外，請確保這些行對齊工整。</p><blockquote><p><strong>提示：</strong> 您需要在插入模式和命令列模式之間來回切換才能完成此任務。</p></blockquote><p>當你完成了，通過 <code>x!</code> 命令保存文件。以上就是 Vim 基本編輯的全部內容。</p><h3 id="第-5-步-vim-中的基本搜索" tabindex="-1">第 5 步：Vim 中的基本搜索 <a class="header-anchor" href="#第-5-步-vim-中的基本搜索" aria-label="Permalink to “第 5 步：Vim 中的基本搜索”">​</a></h3><p>假設你的團隊領導希望你更改項目中的文本字符串。你該如何快速完成任務？你可能希望使用某個關鍵字來搜索該行。</p><p>Vim 的搜索功能非常有用。通過 <code>Esc</code> 鍵來進入命令模式，然後輸入冒號 <code>:</code>，我們可以通過輸入 <code>/&lt;SEARCH_KEYWORD&gt;</code> 來搜索關鍵詞， <code>&lt;SEARCH_KEYWORD&gt;</code> 指你希望搜索的字符串。在這裏，我們搜索關鍵字符串 <code>Hello</code>。在下面的圖示中沒有顯示冒號，但這是必須輸入的。</p><p><img src="https://opensource.com/sites/default/files/uploads/22_searchmode.jpg" alt="Searching in Vim" title="Searching in Vim"></p><p>但是，一個關鍵字可以出現不止一次，而這可能不是你想要的那一個。那麼，如何找到下一個匹配項呢？只需按 <code>n</code> 鍵即可，這代表<ruby>下一個<rt>next</rt></ruby>。執行此操作時，請確保你沒有處於插入模式！</p><h3 id="附加步驟-vim-中的分割模式" tabindex="-1">附加步驟：Vim 中的分割模式 <a class="header-anchor" href="#附加步驟-vim-中的分割模式" aria-label="Permalink to “附加步驟：Vim 中的分割模式”">​</a></h3><p>以上幾乎涵蓋了所有的 Vim 基礎知識。但是，作為一個額外獎勵，我想給你展示 Vim 一個很酷的特性，叫做<ruby>分割<rt>split</rt></ruby>模式。</p><p>退出 <code>HelloWorld.java</code> 並創建一個新文件。在控制台窗口中，輸入 <code>vim GoodBye.java</code> 並按回車鍵來創建一個名為 <code>GoodBye.java</code> 的新文件。</p><p>輸入任何你想輸入的讓內容，我選擇輸入 <code>Goodbye</code>。保存文件（記住你可以在命令模式中使用 <code>:x!</code> 或者 <code>:wq</code>）。</p><p>在命令模式中，輸入 <code>:split HelloWorld.java</code>，來看看發生了什麼。</p><p><img src="https://opensource.com/sites/default/files/uploads/26_copytonewfiles.jpg" alt="Split mode in Vim" title="Split mode in Vim"></p><p>Wow！快看！ <code>split</code> 命令將控制台窗口水平分割成了兩個部分，上面是 <code>HelloWorld.java</code>，下面是 <code>GoodBye.java</code>。該怎麼能在窗口之間切換呢？ 按住 <code>Control</code> 鍵（在 Mac 上）或 <code>Ctrl</code> 鍵（在 PC 上），然後按下 <code>ww</code> (即雙擊 <code>w</code> 鍵)。</p><p>作為最後一個練習，嘗試通過複製和粘貼 <code>HelloWorld.java</code> 來編輯 <code>GoodBye.java</code> 以匹配下面屏幕上的內容。</p><p><img src="https://opensource.com/sites/default/files/uploads/27_exercise.jpg" alt="Modify GoodBye.java file in Split Mode" title="Modify GoodBye.java file in Split Mode"></p><p>保存兩份文件，成功！</p><blockquote><p><strong>提示 1：</strong> 如果你想將兩個文件窗口垂直分割，使用 <code>:vsplit &lt;FILE_NAME&gt;</code> 命令。（代替 <code>:split &lt;FILE_NAME&gt;</code> 命令，<code>&lt;FILE_NAME&gt;</code> 指你想要使用分割模式打開的文件名）。</p><p><strong>提示 2：</strong> 你可以通過調用任意數量的 <code>split</code> 或者 <code>vsplit</code> 命令來打開兩個以上的文件。試一試，看看它效果如何。</p></blockquote><h3 id="vim-速查表" tabindex="-1">Vim 速查表 <a class="header-anchor" href="#vim-速查表" aria-label="Permalink to “Vim 速查表”">​</a></h3><p>在本文中，您學會了如何使用 Vim 來完成工作或項目，但這只是你開啓 Vim 強大功能之旅的開始，可以查看其他很棒的教程和技巧。</p>`,73)),o("p",null,[e[13]||(e[13]=t("為了讓一切變得簡單些，我已經將你學到的一切總結到了 ",-1)),s(i,{href:"https://opensource.com/downloads/cheat-sheet-vim"},{default:d(()=>[...e[12]||(e[12]=[t("一份方便的速查表",-1)])]),_:1}),e[14]||(e[14]=t(" 中。",-1))]),e[36]||(e[36]=o("hr",null,null,-1)),o("p",null,[e[16]||(e[16]=t("via: ",-1)),s(i,{href:"https://opensource.com/article/19/3/getting-started-vim"},{default:d(()=>[...e[15]||(e[15]=[t("https://opensource.com/article/19/3/getting-started-vim",-1)])]),_:1})]),o("p",null,[e[21]||(e[21]=t("作者：",-1)),s(i,{href:"https://opensource.com/users/brson"},{default:d(()=>[...e[17]||(e[17]=[t("Bryant Son",-1)])]),_:1}),e[22]||(e[22]=t(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:d(()=>[...e[18]||(e[18]=[t("lujun9972",-1)])]),_:1}),e[23]||(e[23]=t(" 譯者：",-1)),s(i,{href:"https://github.com/Modrisco"},{default:d(()=>[...e[19]||(e[19]=[t("Modrisco",-1)])]),_:1}),e[24]||(e[24]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:d(()=>[...e[20]||(e[20]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[27]||(e[27]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...e[25]||(e[25]=[t("LCTT",-1)])]),_:1}),e[28]||(e[28]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:d(()=>[...e[26]||(e[26]=[t("Linux中國",-1)])]),_:1}),e[29]||(e[29]=t(" 榮譽推出",-1))])])}const x=l(m,[["render",c]]);export{k as __pageData,x as default};
